/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['bioconductor-deseq2','gseapy','bioconductor-apeglm','bioconductor-org.mm.eg.db']:
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=20'
    try:
        data=json.load(urllib.request.urlopen(url, timeout=20))
        tags=[t['name'] for t in data.get('tags',[])[:10]]
        print(repo)
        for t in tags: print(' ',t)
    except Exception as e:
        print(repo, type(e).__name__, str(e)[:200])
PY"

